{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0006",
          "reason": "This is inherited treaty-signature context, not Bolsonaro-era conduct, so it should stay background rather than do argumentative work as 2022 action."
        },
        {
          "evidence_id": "E0015",
          "reason": "Civil-reactor interest and a peace-flavored quote are only thinly discriminating for nuclear-risk responsibility; keep as weak context, not decisive evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "There is no direct 2022 Bolsonaro-specific decision that materially changed Brazil's nuclear or existential-risk posture.",
          "lenses": ["1B.1", "1B.3", "1B.8", "1B.10"],
          "best_source_or_query_direction": "Bolsonaro-era ANSN appointment/decree history, ABACC/IAEA oversight records, and dated presidential or ministerial statements on civil nuclear policy.",
          "why_it_matters": "Without a target-period ruler choice, the chapter can drift into baseline description instead of conduct."
        }
      ],
      "reason": "Mostly fair and appropriately cautious. It separates Brazil's inherited nonproliferation baseline from Bolsonaro's limited 2022 choices and preserves contrary evidence, but several items are baseline context rather than direct conduct."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0016",
          "reason": "The Moscow visit is useful diplomatic context, but the release itself does not show harmful or protective conduct by Bolsonaro beyond the meeting agenda."
        },
        {
          "evidence_id": "E0025",
          "reason": "A rotating Security Council presidency is procedural context, not substantive peace leadership, so it should not be weighted as direct ruler conduct."
        },
        {
          "evidence_id": "E0027",
          "reason": "The nuclear-weapons warning is better treated as a 1B-adjacent aside; in 2B it should remain subordinate to the Ukraine diplomacy and not count as a separate peace action."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct Bolsonaro-authored foreign-policy speech or transcript evidence is thinner than delegation-level and government-release evidence.",
          "lenses": ["2B.1", "2B.6", "2B.7", "2B.10"],
          "best_source_or_query_direction": "Bolsonaro speeches, Itamaraty transcripts, UN voting explanations, and dated presidential press remarks on Ukraine and Russia.",
          "why_it_matters": "The chapter needs clearer ruler attribution to distinguish Bolsonaro's own choices from ministerial or delegation language."
        }
      ],
      "reason": "Usable and coherent. It documents Bolsonaro's own neutrality rhetoric, Brazil's UN votes, and humanitarian/diplomatic steps while preserving ambiguity about whether those actions were restraint or weak condemnation."
    },
    {
      "chapter_id": "3B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0028",
          "reason": "This is mainly political-rhetoric and democratic-norm evidence; it supports 4B/7B more directly than physical-safety findings in 3B."
        },
        {
          "evidence_id": "E0029",
          "reason": "The report is important context, but its strongest claims are about democratic intimidation and campaign climate rather than direct domestic safety harms."
        },
        {
          "evidence_id": "E0033",
          "reason": "Attacks on the election system are cross-chapter contamination unless tied more tightly to physical violence or state terror; they are stronger 4B/7B evidence."
        },
        {
          "evidence_id": "E0039",
          "reason": "Post-election protest framing is relevant, but it is more about political mobilization and transfer than clear physical-safety conduct."
        },
        {
          "evidence_id": "E0040",
          "reason": "This is indirect protest-stoking evidence; it should be contextualized unless paired with stronger proof of violence or protection failure."
        },
        {
          "evidence_id": "E0041",
          "reason": "Ambiguous post-election exhortation belongs partly in 4B/7B and is only indirectly relevant to 3B's physical-safety nexus."
        },
        {
          "evidence_id": "E0042",
          "reason": "This is mainly a dispute-over-acceptance-of-defeat item, so it should be demoted to context rather than core 3B evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "The package still leans on political intimidation evidence that is better housed in 4B/7B, so the physical-safety nexus is not always clean.",
          "lenses": ["3B.3", "3B.6", "3B.8", "3B.9"],
          "best_source_or_query_direction": "Federal command/tolerance evidence, police and Indigenous-protection records, court findings, and independent outcome data on violence and remedy.",
          "why_it_matters": "Without cleaner ruler-to-harm attribution, 3B risks mixing domestic safety with democratic-backsliding evidence."
        },
        {
          "gap": "Federal attribution remains partial for police violence and local abuse.",
          "lenses": ["3B.1", "3B.2", "3B.4", "3B.10"],
          "best_source_or_query_direction": "Ministry, police, and court records on appointments, policies, oversight, and remedies tied to Bolsonaro's administration.",
          "why_it_matters": "The strongest harms are at the state or local level, so the dossier needs a clearer line from Bolsonaro's authority to the harm."
        }
      ],
      "reason": "Substantively strong on Indigenous harm, police violence, and protection failures, but it mixes in a lot of election-freedom and anti-institution material that belongs more clearly in 4B or 7B."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Source diversity is thin and a lot of the evidence is institutional rebuttal rather than direct Bolsonaro machinery use.",
          "lenses": ["4B.2", "4B.4", "4B.6", "4B.9"],
          "best_source_or_query_direction": "Additional TSE/STF records, campaign filings, presidential statements, and independent election-observer reports from 2022.",
          "why_it_matters": "The chapter is usable, but stronger source mix would make the boundary between rhetoric, pressure, and institutional entrenchment clearer."
        }
      ],
      "reason": "The election and transfer of power are documented, and the package fairly preserves Bolsonaro's fraud narrative, disinformation, and institutional resistance. It is usable despite limited source diversity."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Attribution for macro outcomes remains mixed because several core inputs are country-level or independent-central-bank context rather than direct presidential control.",
          "lenses": ["5B.3", "5B.7", "5B.9", "5B.10"],
          "best_source_or_query_direction": "Independent policy evaluations, budget-execution data, and third-party assessments of Bolsonaro-era fiscal and labor-market measures.",
          "why_it_matters": "The chapter should not over-credit or over-blame Bolsonaro for macro trends that were also driven by shocks and independent institutions."
        }
      ],
      "reason": "Economically coherent and balanced. It contrasts recovery, inflation, fiscal expansion, and household stress while preserving counterforces and attribution limits."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "The dossier is still heavier on policy announcements and administrative design than on independent delivery and outcome evaluation.",
          "lenses": ["6B.2", "6B.4", "6B.5", "6B.9"],
          "best_source_or_query_direction": "Independent take-up/outcome studies for Auxílio Brasil, school connectivity, vaccination, indigenous health, and housing support.",
          "why_it_matters": "Without implementation evidence, the chapter can over-read formal programs as welfare gains."
        },
        {
          "gap": "Racial, regional, and subnational distribution is not fully resolved.",
          "lenses": ["6B.3", "6B.8", "6B.10"],
          "best_source_or_query_direction": "IBGE microdata, UNICEF distributional analysis, and program audits by region and demographic group.",
          "why_it_matters": "The chapter needs to show who benefited, not just that programs existed."
        }
      ],
      "reason": "Fairly presented. It separates the harsh baseline from Bolsonaro-era policy actions and includes both favorable interventions and adverse welfare conditions, though independent implementation evidence would improve confidence."
    },
    {
      "chapter_id": "7B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0086",
          "reason": "This is Flávio Bolsonaro's conduct, not Jair Bolsonaro's direct act; it should be demoted unless paired with stronger evidence that Jair directed, protected, or knowingly tolerated it."
        },
        {
          "evidence_id": "E0090",
          "reason": "Family property transactions spanning decades are relevant background, but they are not a direct Jair Bolsonaro personal act in 2022."
        },
        {
          "evidence_id": "E0092",
          "reason": "The injunction was requested by Flávio Bolsonaro, so it is family-network context rather than direct Jair-specific conduct."
        },
        {
          "evidence_id": "E0093",
          "reason": "This is allegation-level reporting about office transactions and first-family finances; it needs a stronger personal-nexus basis before being treated as decisive integrity evidence."
        },
        {
          "evidence_id": "E0094",
          "reason": "The leak investigation concerns family-network scrutiny, but it remains an allegation and not a finding of Jair Bolsonaro's own dishonesty or obstruction."
        }
      ],
      "material_gaps": [
        {
          "gap": "The package needs a cleaner Jair-specific nexus for self-dealing and concealment, not just family-network allegations.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.7", "7B.9"],
          "best_source_or_query_direction": "Official asset declarations, audit findings, campaign-finance records, appointment files, and court findings directly tied to Jair Bolsonaro.",
          "why_it_matters": "Chapter 7B cannot rest on family-network suspicion alone if the question is Jair Bolsonaro's own integrity."
        },
        {
          "gap": "Appointment evidence is concentrated in Petrobras and is not yet broad enough to test the whole patronage pattern.",
          "lenses": ["7B.5", "7B.9"],
          "best_source_or_query_direction": "Broader cabinet and agency appointment records, governance review material, and conflicts-of-interest findings.",
          "why_it_matters": "A single appointment dispute is informative, but it does not establish the whole integrity pattern."
        }
      ],
      "reason": "This is the shakiest chapter package. It has direct Bolsonaro deception and attack evidence, but a meaningful share of the self-dealing material is family-network or allegation-level evidence that needs tighter personal-nexus handling before final use."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "The package relies heavily on official self-report and only partially on independent outcome validation.",
          "lenses": ["8B.2", "8B.6", "8B.7", "8B.8", "8B.10"],
          "best_source_or_query_direction": "A readable copy of the full TSE-filed 2022 plan plus third-party evaluations of major Bolsonaro programs such as PPI, Renda e Oportunidade, Plan Safra, and Internet Brasil.",
          "why_it_matters": "Execution should be judged on implementation and durable progress, not just on launch announcements."
        },
        {
          "gap": "The evidence for personnel quality and cross-ministry coordination is still thin.",
          "lenses": ["8B.3", "8B.4", "8B.5"],
          "best_source_or_query_direction": "Cabinet/agency staffing records, audit reports, and independent implementation studies on who actually executed the agenda.",
          "why_it_matters": "Competence depends on mobilization and follow-through, not just policy intent."
        }
      ],
      "reason": "Mostly coherent and ideology-neutral. It establishes a program, documents implementation, and keeps macro outcomes separate from moral judgment, but many supporting items are still official self-report or only mixedly attributable."
    }
  ]
}
